import{_ as t,c as s,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"《温公易说》简介","description":"温公易说 - 《温公易说》简介","frontmatter":{"title":"《温公易说》简介","description":"温公易说 - 《温公易说》简介"},"headers":[],"relativePath":"zh/classics/wengong/001.md","filePath":"zh/classics/wengong/001.md"}'),l={name:"zh/classics/wengong/001.md"};function o(c,a,i,d,p,m){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"《温公易说》简介",tabindex:"-1"},[r("《温公易说》简介 "),e("a",{class:"header-anchor",href:"#《温公易说》简介","aria-label":"Permalink to “《温公易说》简介”"},"​")],-1),e("p",null,"《温公易说》是北宋时期著名政治家、史学家司马光的易学著作。司马光，字君实，号迂叟，世称涑水先生，封温国公，故后世称其为司马温公。他历仕仁宗、英宗、神宗、哲宗四朝，官至尚书左仆射兼门下侍郎，反对王安石变法，为保守派领袖，以清廉和正直著称。",-1),e("p",null,"《温公易说》原书已亡佚，现存版本是清代在编纂《四库全书》时从《永乐大典》中辑出的，根据《宋史·艺文志》的记载重新编排为六卷。该书的解说相对简略，对诸卦的解释有多有少，有的卦甚至没有解释，只有《系辞传》部分解说较为详细，而《说卦传》以下的内容仅有两条。一些学者如陈振孙认为这本书并未完成。",-1),e("p",null,"司马光在《温公易说》中主要阐明人事，不杂佛老之说，其解释多不袭先儒旧说，而是以儒家“中庸”思想立论，强调刚柔相济、中正之道。例如，他解释《同人》卦时提出“君子乐与人同，小人乐与人异”，以及《坎》卦的《大象》解释水流和人学习的过程，都显示了他将易学理论联系到日常生活中，使之更贴近实用。",-1),e("p",null,"此书在易学发展史上占有一席之地，成为宋人解《易》中的一个独特流派。通行的版本包括《丛书集成》初编本、《四库全书》本、《经苑》本及《榕园丛书》甲集本。",-1)])])}const h=t(l,[["render",o]]);export{f as __pageData,h as default};
